package io.xeros.solo;
import java.nio.file.*;import java.util.*;import io.xeros.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.content.questing.*;
public class Final70Server {
 public static void main(String[]args)throws Exception{Path folder=Path.of(args[0]);Thread worker=new Thread(()->{String last="";try{while(true){Thread.sleep(300);Player p=PlayerHandler.getPlayerByLoginName("final70qa");if(p==null||!p.isActive)continue;String state="position="+p.getPosition()+"\n";for(Quest q:p.getQuesting().getQuestList())state+=q.getName()+"="+q.getStage()+"\n";state+="dialogue="+(p.getDialogueBuilder()==null?"none":p.getDialogueBuilder().getCurrent().getClass().getSimpleName())+"\n";state+="questpoints="+p.getQuesting().getQuestPoints()+"\nxp7="+p.playerXP[7]+"\n";Files.writeString(folder.resolve("server-state.txt"),state);Path f=folder.resolve("server-action.txt");String action=Files.exists(f)?Files.readString(f).trim():"";if(action.isEmpty()||action.equals(last))continue;last=action;PlayerHandler.addQueuedAction(()->{try{
 if(action.equals("prepare")){p.getRights().setPrimary(Right.OWNER);for(int i=0;i<28;i++)if(p.playerItemsN[i]>0)p.getItems().deleteItem2(p.playerItems[i]-1,p.playerItemsN[i]);p.getPA().closeAllWindows();p.getHealth().setMaximumHealth(99);p.getHealth().reset();p.getItems().addItem(1944,1);p.getItems().addItem(1927,1);p.getItems().addItem(1933,1);p.getQuesting().updateQuestList();p.getPA().movePlayer(3209,3216,0);NPC n=Arrays.stream(NPCHandler.npcs).filter(v->v!=null&&v.getNpcId()==4626&&v.getX()==3209&&v.getY()==3215).findFirst().orElseThrow();Files.writeString(folder.resolve("cook-index.txt"),""+n.getIndex());}
 else if(action.equals("questtab"))new io.xeros.content.commands.all.Quests().execute(p,"quests","");
 else if(action.equals("grave")){p.getPA().closeAllWindows();p.getPA().movePlayer(3250,3193,0);}
 else if(action.equals("save")){if(!PlayerSave.saveGameInstant(p))throw new AssertionError("Save failed");Files.writeString(folder.resolve("save-ok"),"READY");}
 Files.writeString(folder.resolve("server-done.txt"),action);
 }catch(Throwable e){e.printStackTrace();try{Files.writeString(folder.resolve("server-error.txt"),e.toString());}catch(Exception ignored){}}});}}catch(Exception e){e.printStackTrace();}},"V70-fixture");worker.setDaemon(true);worker.start();SoloServer.main(new String[0]);}
}